mapper.select:


    and g.log_type = #{logType}
    and g.action = #{action}
    and g.provider_code = #{providerCode}
    and g.channel_code = #{channelCode}
    and g.out_trade_no like concat('%', #{outTradeNo}, '%')
    and m.phone like concat('%', #{phone}, '%')
    and g.member_id = #{memberId}
    and g.success = #{success}
    
        and g.create_time >= #{params.beginTime}
    
    
        and g.create_time <= #{params.endTime}
    

order by g.log_id desc
